//! Selectable columns of a model.

use crate::model::ErasedColumn;
use crate::model::FilterOperator;
use crate::model::Model;
use serde::Deserialize;
use serde::Serialize;
use std::collections::BTreeSet;

/// One selectable column of a model, generated by `#[derive(DbModel)]` as the
/// `<Model>Column` enum.
///
/// The enum is the only description of a column: the model's
/// [`TableMeta`](crate::TableMeta) holds these same values erased as
/// [`ErasedColumn`], so the two cannot disagree.
///
/// A `#[db(flatten)]` field contributes a variant that wraps the fragment's
/// enum, so a flattened column stays typed and selectable as
/// `FrameColumn::Size(SizeColumn::Width)`.
pub trait Column: Copy + Ord + std::fmt::Debug + Send + Sync + 'static {
    /// The model the column belongs to.
    type Model: Model;

    /// Every column, in declaration order, with a flattened field's columns at
    /// the field's position.
    fn all() -> &'static [Self];

    /// The column name as the database spells it.
    fn name(self) -> &'static str;

    /// The column of that name, or `None` when the model has no such column.
    fn from_name(name: &str) -> Option<Self>;

    /// The column type as DDL spells it: `uuid`, `text`, `varchar(255)`.
    fn pg_type(self) -> &'static str;

    /// The column default as DDL spells it, or `None` when the column has none.
    fn pg_default(self) -> Option<&'static str>;

    /// Whether the column is nullable.
    fn nullable(self) -> bool;

    /// The comparisons the column may be queried with, in declaration order.
    fn query_ops(self) -> &'static [FilterOperator];
}

impl<C: Column> ErasedColumn for C {
    fn name(&self) -> &'static str {
        Column::name(*self)
    }

    fn pg_type(&self) -> &'static str {
        Column::pg_type(*self)
    }

    fn pg_default(&self) -> Option<&'static str> {
        Column::pg_default(*self)
    }

    fn nullable(&self) -> bool {
        Column::nullable(*self)
    }

    fn query_ops(&self) -> &'static [FilterOperator] {
        Column::query_ops(*self)
    }
}

/// A set of columns to select.
///
/// Deserializes from an array of column names, and a name that is not a column
/// of `C` fails to deserialize, so a request never reaches SQL as a string.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(transparent)]
pub struct Columns<C: Column>(BTreeSet<C>);

impl<C: Column> Columns<C> {
    /// Every column of the model.
    pub fn all() -> Self {
        Self(C::all().iter().copied().collect())
    }

    pub fn insert(&mut self, column: C) -> bool {
        self.0.insert(column)
    }

    pub fn remove(&mut self, column: C) -> bool {
        self.0.remove(&column)
    }

    pub fn contains(&self, column: C) -> bool {
        self.0.contains(&column)
    }

    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    pub fn len(&self) -> usize {
        self.0.len()
    }

    /// The columns in declaration order.
    pub fn iter(&self) -> impl Iterator<Item = C> + '_ {
        self.0.iter().copied()
    }

    /// The column names in declaration order, ready for a `SELECT` list.
    pub fn names(&self) -> impl Iterator<Item = &'static str> + '_ {
        self.0.iter().map(|column| Column::name(*column))
    }

    /// The column types in declaration order, as DDL spells them.
    pub fn pg_types(&self) -> impl Iterator<Item = &'static str> + '_ {
        self.0.iter().map(|column| Column::pg_type(*column))
    }
}

impl<C: Column> Default for Columns<C> {
    fn default() -> Self {
        Self(BTreeSet::new())
    }
}

impl<C: Column> FromIterator<C> for Columns<C> {
    fn from_iter<I: IntoIterator<Item = C>>(iter: I) -> Self {
        Self(iter.into_iter().collect())
    }
}

impl<C: Column> IntoIterator for Columns<C> {
    type IntoIter = std::collections::btree_set::IntoIter<C>;
    type Item = C;

    fn into_iter(self) -> Self::IntoIter {
        self.0.into_iter()
    }
}
